    expect(step.decision).toEqual({ allowed: true, remaining: 1, retryAfter: 0, reset: 5 });
    step = takeToken(step.state, policy, 0);
    expect(step.decision).toEqual({ allowed: true, remaining: 0, retryAfter: 0, reset: 10 });
    step = takeToken(step.state, policy, 1_000);
    expect(step.decision).toMatchObject({ allowed: false, remaining: 0, retryAfter: 4 });
    step = takeToken(step.state, policy, 5_000);
    expect(step.decision).toMatchObject({ allowed: true, remaining: 0 });
